func _run_tests() -> void:
	var menu := await instantiate_main_scene()
	if not check("menu", menu != null, "menu.tscn deve istanziarsi correttamente"):
		return
	var container := find_by_name(menu, "TopicsContainer") as VBoxContainer
	if not check("cont", container != null, "TopicsContainer deve essere presente"):
		return
	var buttons := find_all_by_class(container, "Button")
	if not check("btn_count", buttons.size() >= 2, "TopicsContainer deve contenere almeno 2 pulsanti per gli argomenti (trovati: %d)" % buttons.size()):
		return
	var btn_vg: Button = null
	for btn in buttons:
		var b := btn as Button
		if b.text.to_lower().contains("video"):
			btn_vg = b
			break
	if not check("vg_found", btn_vg != null, "Deve esistere un pulsante con titolo contenente 'Videogiochi'"):
		return
	click_button(btn_vg)
	await wait_frames(3)
	var quiz_data := get_node_or_null("/root/QuizData")
	var q_size: int = quiz_data.questions.size() if quiz_data != null and "questions" in quiz_data else 0
	check("loaded", q_size >= 2, "Premendo il pulsante dell'argomento, QuizData.questions deve caricare le domande dell'argomento")

