class_name QuizTopic
extends Resource

@export var title: String = ""
@export var questions: Array[Question] = []


func _init(p_title: String = "", p_questions: Array[Question] = []) -> void:
	title = p_title
	questions = p_questions

# res://menu.gd
extends Control

@export var topic: QuizTopic

@onready var play_button: Button = $CenterContainer/VBoxContainer/PlayButton
@onready var title_label: Label = $CenterContainer/VBoxContainer/TitleLabel


func _ready() -> void:
	if topic:
		title_label.text = "IL QUIZ: " + topic.title.to_upper()
	play_button.grab_focus()
	play_button.pressed.connect(_on_play_button_pressed)


func _on_play_button_pressed() -> void:
	if topic:
		QuizData.questions = topic.questions
	get_tree().change_scene_to_file("res://quiz.tscn")
